  `password` varchar(100) default '',
  `usergroup` text,
  `disable` tinyint(4) unsigned NOT NULL default '0',
  `starttime` int(11) unsigned NOT NULL default '0',
  `endtime` int(11) unsigned NOT NULL default '0',
  `name` varchar(250) character set utf8 collate utf8_danish_ci default NULL,
  `address` text character set utf8 collate utf8_danish_ci,
  `telephone` varchar(50) default '',
  `fax` varchar(50) default '',
  `email` varchar(200) default '',
  `crdate` int(11) unsigned NOT NULL default '0',
  `cruser_id` int(11) unsigned NOT NULL default '0',
  `lockToDomain` varchar(125) default '',
  `deleted` tinyint(3) unsigned NOT NULL default '0',
  `uc` blob NOT NULL,
  `title` varchar(100) character set utf8 collate utf8_danish_ci default NULL,
  `zip` varchar(50) default '',
  `city` varchar(125) default '',
  `country` varchar(150) default '',
  `www` varchar(200) default '',
  `company` varchar(200) default '',
  `image` text,
  `TSconfig` text NOT NULL,
  `fe_cruser_id` int(10) unsigned NOT NULL default '0',
  `lastlogin` int(10) unsigned NOT NULL default '0',
  `is_online` int(10) unsigned NOT NULL default '0',
  `static_info_country` char(8) default '',
  `zone` varchar(113) default '',
  `language` char(5) default '',
  `gender` int(11) unsigned NOT NULL default '0',
  `cnum` varchar(125) default '',
  `first_name` varchar(125) character set utf8 collate utf8_danish_ci default NULL,
  `last_name` varchar(125) character set utf8 collate utf8_danish_ci default NULL,
  `status` int(11) unsigned NOT NULL default '0',
  `date_of_birth` varchar(50) default '0',
  `comments` text NOT NULL,
  `by_invitation` tinyint(4) unsigned NOT NULL default '0',
  `module_sys_dmail_html` tinyint(3) unsigned NOT NULL default '0',
  `felogin_redirectPid` text,
  `municipality` int(11) NOT NULL default '0',
  `department` text NOT NULL,
  `cellphone` text NOT NULL,
  `educations` text NOT NULL,
  `primary_work_areas` int(11) default '0',
  `primary_subject_areas` blob,
  `appointed_to_subject_group` text,
  `other_titles` text NOT NULL,
  `member_of` int(11) NOT NULL default '0',
  `other_memberships` text NOT NULL,
  `special_competences` text NOT NULL,
  `tx_ktckompetencenet_mail_options` int(11) NOT NULL default '0',
  `ktc_subject_groups` text,
  `tx_oelib_is_dummy_record` tinyint(1) unsigned NOT NULL default '0',
  `tx_chcforum_aim` text NOT NULL,
  `tx_chcforum_yahoo` text NOT NULL,
  `tx_chcforum_msn` text NOT NULL,
  `tx_chcforum_customim` text NOT NULL,
  `tx_ktcsettingmailnotification_mail_interval` text NOT NULL,
  `felogin_forgotHash` varchar(200) default '',
  `tx_ktcsettingmailnotification_tx_notifier_lastnotification` int(11) NOT NULL default '0',
  `module_sys_dmail_category` int(10) unsigned NOT NULL default '0',
  `tx_simulatebe_beuser` int(11) unsigned NOT NULL default '0',
  `subscribe_viden` tinyint(3) NOT NULL default '0',
  `subscribe_foreningen` tinyint(3) NOT NULL default '0',
  `subscribe_teknik` tinyint(3) NOT NULL default '0',
  `tx_ktcusers_imported` tinyint(1) default '0',
  `module_sys_dmail_newsletter` tinyint(3) unsigned default '0',
  `usertype` int(11) NOT NULL default '0',
  `tx_ktcusers_old_id` int(11) default NULL,
  `middle_name` varchar(125) NOT NULL default '',
  `tx_extbase_type` text NOT NULL,
  `tx_ktcusers_confirmed` int(3) NOT NULL default '0',
  `virksomheder` text NOT NULL,
  `selskaber` text NOT NULL,
  `virksomh` text NOT NULL,
  `selskab` text NOT NULL,
  `andet` text NOT NULL,
  `tx_ktcusers_virksomheder` text NOT NULL,
  `tx_ktcusers_selskaber` text NOT NULL,
  `tx_ktcusers_virksomhed` text NOT NULL,
  `tx_ktcusers_selskab` text NOT NULL,
  `tx_ktcusers_andet` text NOT NULL,
  PRIMARY KEY  (`uid`),
  KEY `parent` (`pid`,`username`),
  KEY `username` (`username`),
  KEY `is_online` (`is_online`),
  KEY `dummy` (`tx_oelib_is_dummy_record`)
) ENGINE=MyISAM AUTO_INCREMENT=20401 DEFAULT CHARSET=latin1;
SET character_set_client = @saved_cs_client;

